import sys

def rotate_brute(m):
    n = len(m)
    new = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            new[j][n - 1 - i] = m[i][j]
    for i in range(n):
        for j in range(n):
            m[i][j] = new[i][j]
    return m

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    m = []
    idx = 1
    for _ in range(n):
        m.append([int(x) for x in data[idx:idx + n]])
        idx += n
    m = rotate_brute(m)
    for row in m:
        print(' '.join(map(str, row)))

import sys

def rotate_opt(m):
    n = len(m)
    for i in range(n):
        for j in range(i + 1, n):
            m[i][j], m[j][i] = m[j][i], m[i][j]
    for i in range(n):
        m[i].reverse()
    return m

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    m = []
    idx = 1
    for _ in range(n):
        m.append([int(x) for x in data[idx:idx + n]])
        idx += n
    m = rotate_opt(m)
    for row in m:
        print(' '.join(map(str, row)))
